    axis = max(range(h), key=lambda r: sum(v == 6 for v in grid[r]))
    out = [row[:] for row in grid]

    # A vertical bar is a contiguous run of one color through the horizontal
    # axis, with at least one cell of that color above or below it.
    bars = []
    c = 0
    while c < w:
        color = grid[axis][c]
        if color in (6, 8):
            c += 1
            continue

        left = c
        while c + 1 < w and grid[axis][c + 1] == color:
            c += 1
        right = c

        up = down = 0
        for col in range(left, right + 1):
            n = 0
            r = axis - 1
            while r >= 0 and grid[r][col] == color:
                n += 1
                r -= 1
            up = max(up, n)

            n = 0
            r = axis + 1
            while r < h and grid[r][col] == color:
                n += 1
                r += 1
            down = max(down, n)

        if up or down:
            bars.append((left, right, color, up, down))
        c += 1

    # Reassign the vertical heights in increasing order from left to right.
    heights = sorted(bar[3] for bar in bars)
    for (left, right, color, old_up, old_down), new_up in zip(bars, heights):
        for col in range(left, right + 1):
            for d in range(1, max(old_up, old_down, new_up) + 1):
                for r in (axis - d, axis + d):
                    if 0 <= r < h and grid[r][col] == color:
                        out[r][col] = 8
            for d in range(1, new_up + 1):
                if axis - d >= 0:
                    out[axis - d][col] = color
                if axis + d < h:
                    out[axis + d][col] = color

    return out
